package com.sakib.portebo.service;
import android.app.AlarmManager;import android.app.PendingIntent;import android.content.Context;import android.content.Intent;import android.os.Build;import org.json.JSONArray;import org.json.JSONObject;import java.text.SimpleDateFormat;import java.util.Calendar;import java.util.Locale;
public final class AlarmScheduler {private AlarmScheduler(){}
 public static void scheduleDaily(Context c,String start,String end){try{int[] a=parse(start),b=parse(end);Calendar now=Calendar.getInstance(),when=(Calendar)now.clone();when.set(Calendar.HOUR_OF_DAY,a[0]);when.set(Calendar.MINUTE,a[1]);when.set(Calendar.SECOND,0);when.set(Calendar.MILLISECOND,0);if(when.getTimeInMillis()<=now.getTimeInMillis())when.add(Calendar.DAY_OF_YEAR,1);int duration=(b[0]*60+b[1])-(a[0]*60+a[1]);if(duration<=0)duration+=1440;Intent i=new Intent(c,BootReceiver.class).setAction("com.sakib.portebo.DAILY_ROUTINE").putExtra("duration",duration);schedule(c,i,8001,when.getTimeInMillis());}catch(Exception ignored){}}
 public static void scheduleExams(Context c,java.util.List<com.sakib.portebo.model.ExamItem> exams){try{android.content.SharedPreferences p=c.getSharedPreferences("routine_data",0);JSONArray arr=new JSONArray();for(com.sakib.portebo.model.ExamItem x:exams){JSONObject o=new JSONObject();o.put("id",x.getId());o.put("subject",x.getSubject());o.put("date",x.getDate());arr.put(o);}p.edit().putString("exams",arr.toString()).apply();AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(int old=9000;old<10000;old++){Intent prior=new Intent(c,BootReceiver.class).setAction("com.sakib.portebo.EXAM_ROUTINE");PendingIntent pending=PendingIntent.getBroadcast(c,old,prior,PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(pending!=null){am.cancel(pending);pending.cancel();}}JSONArray a=arr;for(int n=0;n<a.length();n++){JSONObject o=a.getJSONObject(n);java.util.Date date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(o.getString("date"));Calendar when=Calendar.getInstance();when.setTime(date);when.add(Calendar.DAY_OF_YEAR,-1);when.set(Calendar.HOUR_OF_DAY,18);when.set(Calendar.MINUTE,0);when.set(Calendar.SECOND,0);when.set(Calendar.MILLISECOND,0);if(when.getTimeInMillis()<=System.currentTimeMillis())continue;Intent i=new Intent(c,BootReceiver.class).setAction("com.sakib.portebo.EXAM_ROUTINE").putExtra("duration",240).putExtra("examId",o.getString("id"));schedule(c,i,9000+n,when.getTimeInMillis());}}catch(Exception ignored){}}
 private static void schedule(Context c,Intent i,int request,long at){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(am==null)return;PendingIntent pi=PendingIntent.getBroadcast(c,request,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{if(Build.VERSION.SDK_INT>=23)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);else am.setExact(AlarmManager.RTC_WAKEUP,at,pi);}catch(SecurityException e){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}}
 private static int[] parse(String s){String[] p=s.split(":");if(p.length!=2)throw new IllegalArgumentException();return new int[]{Math.max(0,Math.min(23,Integer.parseInt(p[0]))),Math.max(0,Math.min(59,Integer.parseInt(p[1])))};}
 public static long getNextLockdownStart(Context c){if(c==null)return 0;long now=System.currentTimeMillis(),best=Long.MAX_VALUE;android.content.SharedPreferences p=c.getApplicationContext().getSharedPreferences("routine_data",Context.MODE_PRIVATE);if(p.getBoolean("daily_enabled",false)){try{int[] t=parse(p.getString("start","18:00"));Calendar x=Calendar.getInstance();x.set(Calendar.HOUR_OF_DAY,t[0]);x.set(Calendar.MINUTE,t[1]);x.set(Calendar.SECOND,0);x.set(Calendar.MILLISECOND,0);if(x.getTimeInMillis()<=now)x.add(Calendar.DAY_OF_YEAR,1);best=Math.min(best,x.getTimeInMillis());}catch(Exception ignored){}}try{JSONArray a=new JSONArray(p.getString("exams","[]"));SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setLenient(false);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;java.util.Date d=f.parse(o.optString("date",""));if(d==null)continue;Calendar x=Calendar.getInstance();x.setTime(d);x.add(Calendar.DAY_OF_YEAR,-1);x.set(Calendar.HOUR_OF_DAY,18);x.set(Calendar.MINUTE,0);x.set(Calendar.SECOND,0);x.set(Calendar.MILLISECOND,0);long at=x.getTimeInMillis();if(at>now)best=Math.min(best,at);}}catch(Exception ignored){}return best==Long.MAX_VALUE?0:best;}
 public static void rescheduleDailyAlarms(Context c){com.sakib.portebo.model.DailyRoutine routine=com.sakib.portebo.data.PrefsManager.getDailyRoutine(c);if(routine.isEnabled())scheduleDaily(c,routine.getStartTime(),routine.getEndTime());android.content.SharedPreferences p=c.getSharedPreferences("routine_data",0);try{JSONArray a=new JSONArray(p.getString("exams","[]"));java.util.List<com.sakib.portebo.model.ExamItem> l=new java.util.ArrayList<>();for(int n=0;n<a.length();n++){JSONObject o=a.getJSONObject(n);l.add(new com.sakib.portebo.model.ExamItem(o.getString("id"),o.getString("subject"),o.getString("date")));}scheduleExams(c,l);}catch(Exception ignored){}}
}
